declare(strict_types=1);require_once __DIR__.'/config/database.php';require_once __DIR__.'/config/public_store_step23.php';$pdo=business_db();$ctx=ps23_admin_ensure($pdo);$user=ps23_guard($pdo,'storefront.export');$rows=ps23_orders($pdo,$ctx['organization_id'],'all');$pdo->prepare("INSERT INTO public_store_exports(organization_id,export_type,row_count,exported_by) VALUES(?,'csv',?,?)")->execute([$ctx['organization_id'],count($rows),(int)$user['id']]);header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="public-order-requests-'.date('Ymd-His').'.csv"');$out=fopen('php://output','w');fputcsv($out,['Order Code','Customer','Mobile','Email','Created','Delivery Mode','MRP Subtotal','VP','Delivery Charge','Estimated Total','Tax Status','Order Status','Payment Status','Lead Linked','Customer Linked','Quote Linked']);foreach($rows as$r)fputcsv($out,[$r['order_code'],$r['customer_name'],$r['mobile'],$r['email'],$r['created_at'],$r['delivery_mode'],$r['subtotal_mrp'],$r['total_vp'],$r['delivery_charge'],$r['estimated_total'],$r['tax_status'],$r['order_status'],$r['payment_status'],!empty($r['lead_id'])?'yes':'no',!empty($r['customer_id'])?'yes':'no',!empty($r['quote_id'])?'yes':'no']);fclose($out);